// ignored. Again is harmless.
func (q *Queries) RecordAnnotationHandoffs(ctx context.Context, arg RecordAnnotationHandoffsParams) error {
	_, err := q.db.Exec(ctx, recordAnnotationHandoffs,
		arg.RunID,
		arg.WorkspaceID,
		arg.ProjectID,
		arg.AnnotationIds,
	)
	return err
}

const softDeleteAnnotation = `-- name: SoftDeleteAnnotation :execrows
UPDATE annotations SET deleted_at = now()
WHERE workspace_id = $1 AND (id = $2 OR parent_id = $2) AND deleted_at IS NULL
`

type SoftDeleteAnnotationParams struct {
	WorkspaceID ids.WorkspaceID
	ID          ids.AnnotationID
}

// Soft delete, replies included.
func (q *Queries) SoftDeleteAnnotation(ctx context.Context, arg SoftDeleteAnnotationParams) (int64, error) {
	result, err := q.db.Exec(ctx, softDeleteAnnotation, arg.WorkspaceID, arg.ID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const updateAnnotation = `-- name: UpdateAnnotation :one
UPDATE annotations
SET start_ms = $1, end_ms = $2, pin = $3, kind = $4, body = $5, status = $6,
    applied_in_run_id = $7, addressed_in_version = $8
WHERE workspace_id = $9 AND id = $10 AND deleted_at IS NULL
RETURNING id, workspace_id, target_type, target_id, project_id, timeline_version, start_ms, end_ms, pin, kind, body, status, parent_id, author_kind, author_id, applied_in_run_id, addressed_in_version, created_at, updated_at, deleted_at
`

type UpdateAnnotationParams struct {
	StartMs            int64
	EndMs              int64
	Pin                []byte
	Kind               string
	Body               string
	Status             string
	AppliedInRunID     pgtype.UUID
	AddressedInVersion *int32
	WorkspaceID        ids.WorkspaceID
	ID                 ids.AnnotationID
}

// Writes every field an edit may change. The service decides the new values from the locked row.
func (q *Queries) UpdateAnnotation(ctx context.Context, arg UpdateAnnotationParams) (Annotation, error) {
	row := q.db.QueryRow(ctx, updateAnnotation,
		arg.StartMs,
		arg.EndMs,
		arg.Pin,
		arg.Kind,
		arg.Body,
		arg.Status,
		arg.AppliedInRunID,
		arg.AddressedInVersion,
		arg.WorkspaceID,
		arg.ID,
	)
	var i Annotation
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.TargetType,
		&i.TargetID,
		&i.ProjectID,
		&i.TimelineVersion,
		&i.StartMs,
		&i.EndMs,
		&i.Pin,
		&i.Kind,
		&i.Body,
		&i.Status,
		&i.ParentID,
		&i.AuthorKind,
		&i.AuthorID,
		&i.AppliedInRunID,
		&i.AddressedInVersion,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.DeletedAt,
	)
	return i, err
}
